assert_eq!(UtcDateTime::MAX.checked_add(1.days()), None);
assert_eq!(
    utc_datetime!(2019-11-25 15:30).checked_add(27.hours()),
    Some(utc_datetime!(2019-11-26 18:30))
);
```

Computes `self - duration`, returning `None` if an overflow occurred.

```rust
